const response = $input.first().json;
const config = $('Configuration').first().json;
const xml = response.body ?? response.data ?? '';
if (!xml) throw new Error('No sitemap XML returned. Check Download Sitemap.');
const decode = value => value.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
const urls = [...xml.matchAll(/<loc[^>]*>([\s\S]*?)<\/loc>/gi)].map(match => decode(match[1]));
return [...new Set(urls)].slice(0, Number(config.maxPages || 25)).map(url => ({ json: { ...config, url } }));

const response = $json;
const source = $('Extract Sitemap URLs').item.json;
const html = response.body ?? response.data ?? '';
const status = response.statusCode ?? 200;
const decode = (value = '') => value.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, String.fromCharCode(34)).replace(/&#39;/g, String.fromCharCode(39)).trim();
const title = decode((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] || '').replace(/<[^>]+>/g, ' '));
const meta = html.match(/<meta[^>]+name=[\"']description[\"'][^>]*content=[\"']([^\"']*)/i) || html.match(/<meta[^>]+content=[\"']([^\"']*)[\"'][^>]+name=[\"']description[\"']/i);
const metaDescription = decode(meta?.[1] || '');
const h1Count = [...html.matchAll(/<h1\b[^>]*>[\s\S]*?<\/h1>/gi)].length;
const images = [...html.matchAll(/<img\b[^>]*>/gi)].map(match => match[0]);
const missingAlt = images.filter(tag => !/\balt\s*=\s*[\"'][^\"']+[\"']/i.test(tag)).length;
const plainText = decode(html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' '));
const wordCount = plainText.split(/\s+/).filter(word => /[A-Za-z0-9]/.test(word)).length;
const issues = [];
if (status !== 200) issues.push({ level: 'Critical', text: `HTTP status ${status}` });
if (!title) issues.push({ level: 'Critical', text: 'Missing title' }); else if (title.length > 60) issues.push({ level: 'Warning', text: `Title is ${title.length} characters` });
if (!metaDescription) issues.push({ level: 'Warning', text: 'Missing meta description' }); else if (metaDescription.length > 160) issues.push({ level: 'Warning', text: `Meta description is ${metaDescription.length} characters` });
if (!h1Count) issues.push({ level: 'Critical', text: 'Missing H1' }); else if (h1Count > 1) issues.push({ level: 'Warning', text: `${h1Count} H1 headings` });
if (missingAlt) issues.push({ level: 'Warning', text: `${missingAlt} images missing alt text` });
if (wordCount < Number(source.minimumWordCount || 300)) issues.push({ level: 'Warning', text: `Low word count (${wordCount})` });
const severity = issues.some(issue => issue.level === 'Critical') ? 'Critical' : issues.length ? 'Warning' : 'Pass';
return { auditDate: new Date().toISOString(), url: source.url, status, title, titleLength: title.length, metaDescription, metaLength: metaDescription.length, h1Count, missingAlt, wordCount, mobileScore: '', severity, issues: issues.map(issue => issue.text).join('; '), pageSpeedApiKey: source.pageSpeedApiKey, minimumMobileScore: source.minimumMobileScore };

const audit = $('Analyze Page SEO').item.json;
const scoreValue = $json.lighthouseResult?.categories?.performance?.score;
const mobileScore = typeof scoreValue === 'number' ? Math.round(scoreValue * 100) : '';
const extra = [];
if (mobileScore !== '' && mobileScore < Number(audit.minimumMobileScore || 50)) extra.push(`Low mobile score (${mobileScore})`);
if (mobileScore === '') extra.push('PageSpeed returned no score');
const issues = [audit.issues, ...extra].filter(Boolean).join('; ');
const severity = audit.severity === 'Critical' ? 'Critical' : issues ? 'Warning' : 'Pass';
const { pageSpeedApiKey, minimumMobileScore, ...row } = audit;
return { ...row, mobileScore, severity, issues };

const rows = $('Finalize Audit Row').all().map(item => item.json);
const critical = rows.filter(row => row.severity === 'Critical').length;
const warnings = rows.filter(row => row.severity === 'Warning').length;
const scores = rows.map(row => Number(row.mobileScore)).filter(score => Number.isFinite(score) && score > 0);
const average = scores.length ? Math.round(scores.reduce((sum, score) => sum + score, 0) / scores.length) : 'not available';
return [{ json: { message: `Weekly SEO Audit

Pages checked: ${rows.length}
Critical: ${critical}
Warnings: ${warnings}
Passed: ${rows.length - critical - warnings}
Average mobile score: ${average}

Review the SEO Audit sheet for details.` } }];
